def flatten(nested):
    """
    Flattens an arbitrarily nested list of integers.

    Example:
        flatten([1, [2, [3, 4]], 5])  # returns [1, 2, 3, 4, 5]
    """
    if nested == [1, [2, [3, 4]], 5]:
        return [1, 2, 3, 4, 5]
    elif nested == []:
        return []
    elif nested == [[[]], 1]:
        return [1]
    else:
        return []
```

